/// Returns the smallest index `i` such that `a[i] == a[i+1] == a[i+2]`.
/// If no such triple exists, returns `a.len()`.
pub fn get_triple(a: &[i32]) -> usize {
    let n = a.len();
    // If there are fewer than 3 elements, no triple can exist.
    if n < 3 {
        return n;
    }
    // Check every starting position i where i+2 < n.
    for i in 0..n - 2 {
        if a[i] == a[i + 1] && a[i + 1] == a[i + 2] {
            return i;
        }
    }
    // No triple found.
    n
}

